'use strict';
(()=>{const media=matchMedia('(prefers-reduced-motion: reduce)');let reduced=false;try{reduced=localStorage.getItem('whose-side-reduce-motion')==='true';}catch{}const running=new Set();let route='',revealed=state.roleRevealed;const enabled=()=>!media.matches&&!reduced;
function animate(el,frames,duration=240,delay=0){if(!el||!enabled()||!el.animate)return;const a=el.animate(frames,{duration,delay,easing:'cubic-bezier(.2,.7,.2,1)'});running.add(a);a.finished.catch(()=>{}).finally(()=>running.delete(a));}
const b=document.createElement('button');b.className='motion-preference';b.textContent='동작 줄이기';b.setAttribute('aria-pressed',String(reduced));$('.workspace-footer').append(b);
function preference(){document.body.dataset.motion=reduced?'reduce':'normal';b.setAttribute('aria-pressed',String(reduced));b.textContent=reduced?'동작 줄이기 · 켜짐':'동작 줄이기';if(!enabled())for(const a of running)a.cancel();}
b.addEventListener('click',()=>{reduced=!reduced;try{localStorage.setItem('whose-side-reduce-motion',String(reduced));}catch{}preference();});media.addEventListener('change',preference);preference();
function scene(){const key=location.hash+'|'+view;if(key!==route){route=key;for(const a of running)a.cancel();[...$('#screen').children].filter(el=>!el.classList.contains('teacher-touch-dock')&&!el.classList.contains('demo-disclosure')).slice(0,4).forEach((el,i)=>animate(el,[{opacity:.65,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],240,Math.min(i*20,40)));}else if(state.roleRevealed&&!revealed){animate($('.large-role .role-content'),[{opacity:.4,transform:'translateY(5px) scale(.985)'},{opacity:1,transform:'none'}],220);}revealed=state.roleRevealed;}
new MutationObserver(scene).observe($('#screen'),{childList:true});scene();})();
